/* Local-only interface. Original source text is never modified by review answers. */
(()=>{'use strict';
const E=window.CREM,D=window.CREM_DATA,R=window.CREM_REAGENTS||[],BUILD=window.CREM_BUILD||(D.records&&D.records.length?'registry':'blank'),KEY='lemonaid-'+BUILD+'-v1';
const VERSION=window.LEMONAID_VERSION||'dev';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const badge=(x,type='')=>`<span class="badge ${type}">${esc(x)}</span>`;
const fresh=()=>({version:1,source:{...D.source,mode:D.records.length?'registry':'import'},records:structuredClone(D.records),map:{...E.DEFAULT_MAP},pmap:E.provenanceMap(Object.keys((D.records[0]||{raw:{}}).raw)),norm:{},lastExport:'',selected:D.source.default_selected||(D.records[0]||{}).key||'',goal:'share',reviews:{},view:'inventory'});
let state=fresh(),search='',filter='all',labFilter='all',sortBy='row',pending=null,storageOK=true;
const BRAND=D.brand||{name:'LemonAId',sub:'YOUR DATA. A CLEARER PATH.'};
function empty(){return !state.records.length;}
const goalLabel=g=>(E.GOALS.find(x=>x[0]===g)||E.GOALS[0])[1];
function validateSession(s){
 if(!s||s.version!==1||!Array.isArray(s.records)||s.records.length>10000||!s.source||!s.map)throw Error('This is not a supported LemonAId session.');
 const keys=new Set();s.records.forEach((r,i)=>{if(!r||typeof r.key!=='string'||keys.has(r.key)||!r.raw||typeof r.raw!=='object'||Array.isArray(r.raw))throw Error('Invalid or duplicate record keys.');keys.add(r.key);for(const v of Object.values(r.raw))if(typeof v!=='string')throw Error('Source values must be text.');r.row=Number.isInteger(r.row)&&r.row>0?r.row:i+2;});
 const map=Object.fromEntries(E.FIELDS.map(([k])=>[k,typeof s.map[k]==='string'?s.map[k]:''])),reviews={};
 for(const r of s.records){const rev=s.reviews?.[r.key];if(rev)reviews[r.key]={answers:E.validAnswers(rev.answers),drafts:rev.drafts?E.validAnswers(rev.drafts):null,files:String(rev.files||''),owners:Object.fromEntries(Object.entries(rev.owners||{}).map(([k,v])=>[k,String(v)])),notes:Object.fromEntries(Object.entries(rev.notes||{}).map(([k,v])=>[k,String(v)])),validation:rev.validation&&typeof rev.validation==='object'?{sheet:String(rev.validation.sheet||'').slice(0,2_000_000),listing:String(rev.validation.listing||'').slice(0,5_000_000),excluded:String(rev.validation.excluded||'').slice(0,200_000),panel:String(rev.validation.panel||'').slice(0,2_000_000),ran:String(rev.validation.ran||'')}:null};}
 const norm={};for(const f of Object.keys(E.NORM_TARGETS)){norm[f]={};for(const [k,v] of Object.entries(s.norm?.[f]||{}))if(v&&typeof v==='object')norm[f][String(k)]={term:String(v.term||''),reviewer:String(v.reviewer||'')};}
 const headers=Object.keys((s.records[0]||{raw:{}}).raw);const pmap=s.pmap&&typeof s.pmap==='object'?Object.fromEntries(E.PROV_FIELDS.map(([k])=>[k,typeof s.pmap[k]==='string'?s.pmap[k]:''])):E.provenanceMap(headers);
 return {version:1,norm,pmap,lastExport:String(s.lastExport||''),scenario:['recover','partial','blocked'].includes(s.scenario)?s.scenario:'recover',source:{name:String(s.source.name||'Imported inventory'),mode:s.source.mode==='carlos'?'registry':['registry','demo','import'].includes(s.source.mode)?s.source.mode:'import',path:String(s.source.path||''),sha256:String(s.source.sha256||''),sheet:String(s.source.sheet||''),records:s.records.length},records:s.records,map,selected:keys.has(s.selected)?s.selected:(s.records[0]||{}).key||'',goal:E.GOALS.some(g=>g[0]===s.goal)?s.goal:'share',reviews,view:['inventory','structure','connections','actions','future'].includes(s.view)?s.view:'inventory'};
}
try{let saved=localStorage.getItem(KEY);if(!saved&&BUILD==='registry')saved=localStorage.getItem('crem-readiness-v1');if(saved){const s=validateSession(JSON.parse(saved));if(!(BUILD==='blank'&&s.source.mode==='registry'))state=s;}}catch{storageOK=false;}
function ago(iso){if(!iso)return 'never exported';const m=Math.round((Date.now()-new Date(iso))/60000);return m<1?'exported just now':m<60?`exported ${m} min ago`:m<1440?`exported ${Math.round(m/60)} h ago`:`exported ${Math.round(m/1440)} d ago`;}
let dirtySinceExport=false;
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch{storageOK=false;}dirtySinceExport=true;const notes=Object.values(state.reviews).some(r=>Object.keys(r.answers||{}).length||Object.values(r.notes||{}).some(Boolean));$('#save-state').textContent=storageOK?`Saved only in this browser · session ${ago(state.lastExport)}${notes&&!state.lastExport?' · export a session to keep your notes':''}`:'Browser storage unavailable · export a session to keep your notes';}
// Notes live only in this browser until file-backed sessions arrive (v0.8.0); warn before the page is left with unexported notes.
if(typeof window.addEventListener==='function')window.addEventListener('beforeunload',e=>{const notes=Object.values(state.reviews).some(r=>Object.keys(r.answers||{}).length||Object.values(r.notes||{}).some(Boolean));if(notes&&dirtySinceExport){e.preventDefault();e.returnValue='Your notes are saved only in this browser. Export a session to keep them.';}});
function record(){return state.records.find(r=>r.key===state.selected)||state.records[0];}
function project(){return E.canonical(record(),state.map);}
function review(){return state.reviews[state.selected]||(state.reviews[state.selected]={answers:{},files:'',owners:{},notes:{},validation:null});}
function plan(){return E.plan(record(),state.map,review().answers,state.goal,state.records);}
function sourceLabel(){return empty()?'No inventory loaded':state.source.mode==='demo'?'Illustrative teaching example':state.source.mode==='registry'?(D.source.label||'Embedded inventory'):'Imported inventory';}
function labOf(r){const p=E.canonical(r,state.map);return E.missing(p.lab)?'Unassigned':p.lab;}
const REACH_DEF={'Public accession':'An accession in a public repository is recorded; anyone can find, cite and download the data.','Viewer only':'An interactive viewer link is recorded and no accession; anyone with the link can browse one analysis but cannot download, cite or reprocess.','Local only':'Neither; the dataset can be found only by asking the lab or the core that made it.'};
function reach(p){return E.hasAccession(p)?['Public accession','green']:(!E.missing(p.shinyapp_link)||!E.missing(p.analysis_visualization_link))?['Viewer only','']:['Local only','neutral'];}
function reachBadge(p){const [l,t]=reach(p);return `<span class="badge ${t}" title="${esc(REACH_DEF[l])}">${esc(l)}</span>`;}
function evidenceCount(key){const rev=state.reviews[key];if(!rev)return 0;return Object.values(rev.answers||{}).filter(x=>x&&x.value!=='unknown'&&String(x.evidence||'').trim()).length;}
function title(){return E.missing(project().Dataset_Name)?'Untitled project':project().Dataset_Name;}
function sourceCitation(){return `${state.source.name} · ${state.source.sheet?state.source.sheet+' · ':''}record row ${record().row}`;}
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,4500);}
function navigate(view){state.view=view;render();window.scrollTo({top:0,behavior:'instant'});$('#content').focus({preventScroll:true});}
function heading(step,name,description){return `<div class="page-head"><div><div class="eyebrow">${step}</div><h1>${name}</h1><p class="lede">${description}</p></div>${state.source.mode==='registry'?badge('SOURCE INVENTORY','green'):badge(state.source.mode==='demo'?'ILLUSTRATIVE ONLY':'IMPORTED SOURCE','amber')}</div>`;}
function context(){
 const groups=new Map();for(const r of state.records){const l=labOf(r);if(!groups.has(l))groups.set(l,[]);groups.get(l).push(r);}
 const opt=r=>{const p=E.canonical(r,state.map);return `<option value="${esc(r.key)}" ${r.key===state.selected?'selected':''}>${esc(E.missing(p.Dataset_Name)?(p.project_id||'Untitled row '+r.row)+' (untitled)':p.Dataset_Name)}</option>`;};
 const options=groups.size>1?[...groups.entries()].sort((x,y)=>x[0].localeCompare(y[0])).map(([l,rs])=>`<optgroup label="${esc(l)}">${rs.map(opt).join('')}</optgroup>`).join(''):state.records.map(opt).join('');
 return `<div class="project-context"><div class="field"><label for="project-select">Project in focus</label><select id="project-select">${options}</select></div><div class="field goal"><label for="goal-select">Intended use</label><select id="goal-select">${E.GOALS.map(([v,l])=>`<option value="${v}" ${state.goal===v?'selected':''}>${l}</option>`).join('')}</select></div></div>`;}
function demoBanner(){return state.source.mode==='demo'?`<div class="demo-controls"><strong>Teaching example: every sample, file path and answer below is fictional.</strong><div class="row"><label for="demo-case">Scenario</label><select id="demo-case"><option value="recover" ${!state.scenario||state.scenario==='recover'?'selected':''}>Messy, recoverable metadata</option><option value="partial" ${state.scenario==='partial'?'selected':''}>Files located; sample crosswalk still missing</option><option value="blocked" ${state.scenario==='blocked'?'selected':''}>Sample identity cannot be recovered</option></select><button class="button small" id="apply-demo">Load scenario</button>${D.records.length?'<button class="button small" id="restore-registry">Return to the registry</button>':''}</div></div>`:'';}
function sourceDetails(){const p=project();return `<div class="panel"><div class="panel-title"><h2>What the source actually says</h2>${badge('Observed text','green')}</div><p class="hint">${esc(sourceCitation())}. Original text is retained below. External links have not been opened or verified.</p>${provenanceBadges()}<dl class="facts">${E.FIELDS.map(([k,label])=>`<div><dt>${esc(label)}</dt><dd>${['analysis_visualization_link','shinyapp_link'].includes(k)?urlLinks(p[k]):esc(p[k]||'(blank)')}</dd></div>`).join('')}</dl><details style="margin-top:18px"><summary class="hint">All original columns, including unmapped fields</summary><div class="table-wrap"><table>${Object.entries(record().raw).map(([k,v])=>`<tr><td>${esc(k)}</td><td>${esc(v)}</td></tr>`).join('')}</table></div></details></div>`;}
function provenanceBadges(){const r=record(),pm=state.pmap||{};const lab=E.provenanceOf(r,pm,'lab'),pur=E.provenanceOf(r,pm,'purpose_of_experiment');if(!pm.lab_assignment&&!pm.purpose_source)return '';const tone={recorded:'green',inferred:'amber',absent:'neutral',llm_written:'amber',suspect:'amber'};const word={recorded:'recorded',inferred:'inferred from paths',absent:'not assigned',llm_written:'written by an LLM from code',suspect:'suspect text'};return `<div class="prov"><span class="callout-label">Provenance</span>${pm.lab_assignment?badge('lab: '+word[lab],tone[lab]):''}${pm.purpose_source?badge('purpose: '+word[pur],tone[pur]):''}${badge('evidence: '+(evidenceCount(r.key)?evidenceCount(r.key)+' user-reported':'none yet'),evidenceCount(r.key)?'green':'neutral')}</div>`;}
function urlLinks(value){if(E.missing(value))return esc(value||'(blank)');return value.split(/;\s*/).map(s=>{try{const u=new URL(s.trim());if(!['https:','http:'].includes(u.protocol))return esc(s);return `<a href="${esc(u.href)}" target="_blank" rel="noopener noreferrer">${esc(s)}</a>`;}catch{return esc(s);}}).join('<br>');}
function findings(){const p=project(),sp=E.species(p);return `<div class="panel"><div class="eyebrow">FROM INVENTORY TO PLAN</div><h2>What needs a closer look</h2><div class="finding"><strong>Project records are not sample records</strong>Sample, run, library and acquisition links have not been validated. Check the original and unmapped columns for existing identifiers first.</div><div class="finding"><strong>Species and reference are mixed</strong>“${esc(p.genome_reference||'(blank)')}” → proposed organism: ${esc(sp.organism)}; assembly: ${esc(sp.assembly)}. Verify before accepting.</div><div class="finding"><strong>Reporters are biological context</strong>“${esc(p.reporters||'(blank)')}” does not prove flow data exist or that assays are paired.</div><div class="finding"><strong>Public reach</strong>${!E.missing(p.geo_accession)?`Accession ${esc(p.geo_accession)} is recorded. Others can cite and reprocess this dataset.`:(!E.missing(p.shinyapp_link)||!E.missing(p.analysis_visualization_link))?'A viewer is recorded but no public accession. A viewer serves one analysis; it cannot be cited, mirrored or reprocessed.':'No viewer and no public accession (local only). Only the people who made it can currently find this dataset.'}</div>${state.source.mode==='registry'?`<div class="finding"><strong>The date is the Core’s intake date</strong>Source header <code>${esc(state.map.project_date||'(unmapped)')}</code>. In the registry it is the day the Core opened the project, not the acquisition date.</div>`:`<div class="finding"><strong>Confirm what the date means</strong>Source header <code>${esc(state.map.project_date||'(unmapped)')}</code>. Intake, acquisition and analysis dates differ; record which one this is.</div>`}<button class="button primary" data-view="structure" style="margin-top:20px">See suggested structure →</button></div>`;}
function shortlistPanel(){const list=E.shortlist(state.records,state.map,10,state.reviews);if(!list.length)return '';const tieNote=list.tied>1?` ${list.tied} of ${list.total} projects share the top score of ${list.top}/8; ${E.SHORTLIST_TIEBREAK}`:'';return `<div class="panel"><div class="panel-title"><div><h2>Closest to shareable, by what the inventory records</h2><p class="hint" style="margin:5px 0 0">The ten highest-scoring projects without a public accession. ${esc(E.READINESS_RULE)}${esc(tieNote)} Every project's score is in the Recorded column of the table below; sort by it to see the whole list.</p></div></div><div class="table-wrap"><table class="shortlist"><thead><tr><th>Project</th><th>Laboratory</th><th>Recorded</th><th>Needs next</th></tr></thead><tbody>${list.map((x,i)=>`<tr><td><span class="rank">${i+1}</span><button class="project-link" data-project="${esc(x.record.key)}">${esc(E.missing(x.p.Dataset_Name)?x.p.project_id:x.p.Dataset_Name)}</button><span class="source-id">${esc(x.p.project_id)}${x.p.project_date?' · '+esc(x.p.project_date):''}</span></td><td>${esc(labOf(x.record).replace(/ Lab$/,''))}</td><td class="ev">${x.score}/8${x.viewer?' · viewer':''}</td><td>${esc(x.next)}</td></tr>`).join('')}</tbody></table></div></div>`;}
function queriesPanel(){const qs=E.queryReadiness(state.records,state.map,state.reviews);return `<div class="panel"><div class="panel-title"><div><h2>${E.QUERIES_SOURCE?'Which of the center\'s questions could be answered today?':'Which questions could your project list answer today?'}</h2><p class="hint" style="margin:5px 0 0">A baseline: how many projects could answer each question from what is recorded and checked so far, so progress can be measured against it. ${esc((window.LEMONAID_QUERIES&&window.LEMONAID_QUERIES.panel_intro)||'Each requirement under a question is something the inventory or your evidence notes have to record. A center can replace these questions with its own.')} A requirement badge counts projects meeting that one requirement; the large figure counts projects meeting all of them.${E.QUERIES_SOURCE?' Questions: '+esc(E.QUERIES_SOURCE)+'.':''}</p></div></div>${qs.map(q=>`<div class="query ${q.horizon?'horizon':''}"><div class="qhead"><strong>${esc(q.title)}</strong><span class="qcount">${q.horizon?'horizon, not a deliverable':`<b>${q.ready}</b> of ${q.n} projects meet all requirements`}</span></div><p class="hint" style="margin:4px 0 8px">${esc(q.source)} · needs all of:</p><div class="needs">${q.needs.map(n=>`<span class="need ${n.count?'':'zero'}"><i>${n.count}</i>${esc(n.label)} <span class="muted">· met by ${n.count}</span></span>`).join('')}</div></div>`).join('')}</div>`;}
function emptyPanel(){return heading('01 / UNDERSTAND THE STARTING POINT','Where does a lab start?','Start with what you already have: the folder your projects live in, or the spreadsheet you already keep. LemonAId shows what is recorded, what is missing, and what to do next so the data can be found and reused by others. Nothing leaves this computer.')+`<div class="panel"><h2>Bring your projects in</h2><div class="doors"><div class="door"><strong>Your projects folder</strong><span>One project per folder. LemonAId reads file names, dates and README text; it never opens an assay file.</span></div><div class="door"><strong>Your spreadsheet</strong><span>CSV or TSV, one row per project, any column names.</span></div><div class="door"><strong>Nothing yet</strong><span>Download a template with the columns labs and cores already use.</span></div></div><div class="row"><button id="import-open" class="button primary">Start</button><button id="load-example" class="button">Try the example inventory</button><button id="load-demo" class="button quiet">Open the teaching example</button></div></div>`;}
function completenessPanel(){const c=E.completeness(state.records,state.map),n=c.n||1;const labels=Object.fromEntries(E.FIELDS);const rows=E.READINESS_FIELDS.map(f=>[labels[f],c.fields[f]]).sort((x,y)=>y[1]-x[1]);return `<div class="panel"><div class="panel-title"><div><h2>What the inventory already records</h2><p class="hint" style="margin:5px 0 0">Share of ${c.n} records with each field filled in. Empty and “NA” count as missing. This is coverage of the inventory, not quality of the data behind it.</p></div></div><div class="completeness">${rows.map(([l,v])=>`<div class="crow"><span class="clabel">${esc(l)}</span><span class="cbar"><i style="width:${Math.round(100*v/n)}%"></i></span><span class="cval">${Math.round(100*v/n)}%</span></div>`).join('')}</div></div>`;}
function inventory(){if(empty())return emptyPanel();const all=state.records.map(r=>E.canonical(r,state.map));const c=E.completeness(state.records,state.map);const missingNames=all.filter(p=>E.missing(p.Dataset_Name)).length;const coreOnly=all.filter(p=>reach(p)[0]==='Local only').length;return heading('01 / UNDERSTAND THE STARTING POINT','Where does a lab start?','Begin with the inventory you already keep. The planner shows what it records, what it leaves out, and turns each project into a short list of things someone has to check before the data can be found and reused by others.')+demoBanner()+`<div class="banner"><strong>This is the inventory as received.</strong> Nothing in it has been checked against the files it describes. The plan you build on the later screens records who checked what, and where.</div><div class="stats"><div class="stat"><strong>${all.length}</strong><span>project records<br>${esc(sourceLabel())}</span></div><div class="stat"><strong>${c.geo}</strong><span>with a public accession<br>citable and reprocessable by others</span></div><div class="stat"><strong>${all.filter(p=>reach(p)[0]==='Viewer only').length}</strong><span>viewer only<br>browsable, not citable</span></div><div class="stat"><strong>${coreOnly}</strong><span>${state.source.mode==='registry'?'reachable only through the Core':'reachable only through the lab'}<br>${missingNames} of them also lack a name</span></div></div><p class="hint legend"><strong>Reach</strong> is the most public place the inventory records for a dataset, not a judgement of the data. Only a repository identifier (GSE, E-MTAB, PRJNA and similar) counts as an accession${c.accessionText?`; ${c.accessionText} record${c.accessionText===1?' has':'s have'} other text in the accession field and count as not deposited`:''}. ${Object.entries(REACH_DEF).map(([k,v])=>`<em>${k}</em>: ${v}`).join(' ')}</p>${completenessPanel()}${shortlistPanel()}${queriesPanel()}<div class="panel flush"><div class="filters"><input type="search" id="project-search" class="search" aria-label="Search projects" placeholder="Search project, person, reporter or purpose…" value="${esc(search)}"><select id="lab-filter" aria-label="Filter by laboratory"><option value="all">All laboratories</option>${[...new Set(state.records.map(labOf))].sort().map(l=>`<option value="${esc(l)}" ${labFilter===l?'selected':''}>${esc(l)}</option>`).join('')}</select><select id="project-filter" aria-label="Filter by status"><option value="all" ${filter==='all'?'selected':''}>All records</option><option value="single" ${filter==='single'?'selected':''}>Single-cell RNA</option><option value="unknown" ${filter==='unknown'?'selected':''}>Assay type to confirm</option><option value="core" ${filter==='core'?'selected':''}>Local only (no viewer, no accession)</option><option value="public" ${filter==='public'?'selected':''}>With a public accession</option><option value="missing" ${filter==='missing'?'selected':''}>Missing dataset name</option><option value="acctext" ${filter==='acctext'?'selected':''}>Accession field holds other text</option><option value="reviewed" ${filter==='reviewed'?'selected':''}>With evidence recorded</option></select></div><div class="table-wrap"><table class="inventory-table"><thead><tr><th>Project / dataset</th><th>Laboratory</th><th>Assay, as recorded</th><th>Reach</th><th><button class="th-sort" data-sort="score" title="${esc(E.READINESS_RULE)}">Recorded ${sortBy==='score'?'▾':''}</button></th><th>Evidence</th></tr></thead><tbody id="project-rows"></tbody></table></div><div style="padding:11px 20px" id="record-count"></div></div>${context()}<div class="split">${sourceDetails()}${findings()}</div><div class="panel"><div class="panel-title"><div><h3>Try the flow + scRNA-seq walkthrough</h3><p class="hint" style="margin:5px 0 0">A fictional project shows how the plan changes as evidence is recorded.</p></div><button id="load-demo" class="button">Open teaching example</button></div><button id="restore-registry" class="button quiet" ${state.source.mode==='registry'||!D.records.length?'hidden':''}>Return to the registry</button></div>`;}
function renderRows(){if(!$('#project-rows'))return;const q=search.toLowerCase();const selected=state.records.filter(r=>{const p=E.canonical(r,state.map),tags=E.classify(p);if(labFilter!=='all'&&labOf(r)!==labFilter)return false;if(q&&!Object.values(r.raw).join(' ').toLowerCase().includes(q))return false;return filter==='all'||filter==='single'&&tags.some(t=>/scRNA|snRNA|single-cell/.test(t))||filter==='unknown'&&tags.includes('Assay type to confirm')||filter==='core'&&reach(p)[0]==='Local only'||filter==='public'&&reach(p)[0]==='Public accession'||filter==='missing'&&E.missing(p.Dataset_Name)||filter==='acctext'&&!!E.accessionNote(p)||filter==='reviewed'&&evidenceCount(r.key)>0;});const total=E.applicableQuestions(state.goal).length;if(sortBy==='score')selected.sort((x,y)=>E.readiness(E.canonical(y,state.map)).score-E.readiness(E.canonical(x,state.map)).score);$('#project-rows').innerHTML=selected.length?selected.map(r=>{const p=E.canonical(r,state.map),[rl,rt]=reach(p),ev=evidenceCount(r.key),rd=E.readiness(p);return `<tr class="${r.key===state.selected?'selected-row':''}"><td><button class="project-link" data-project="${esc(r.key)}">${esc(E.missing(p.Dataset_Name)?'Untitled, context needed':p.Dataset_Name)}</button><span class="source-id">${esc(p.project_id||'Missing project ID')}${E.missing(p.project_date)?'':' · '+esc(p.project_date)}</span></td><td>${esc(labOf(r).replace(/ Lab$/,''))}</td><td>${E.classify(p).map(t=>badge(t,t.includes('confirm')?'neutral':/Accession field|disagree/.test(t)?'warn':'')).join('')}</td><td>${reachBadge(p)}</td><td class="ev" title="${esc(E.READINESS_RULE)}">${rd.shared?'shared':rd.score+'/8'}</td><td class="ev">${ev?`${ev}/${total}`:'<span class="muted">none</span>'}</td></tr>`;}).join(''):'<tr><td colspan="6" class="empty">No matching records. Try a broader search or another filter.</td></tr>';$('#record-count').textContent=`Showing ${selected.length} of ${state.records.length} records. Assay tags repeat the source wording. Recorded is the 0 to 8 score described above (hover the heading); click it to sort.`;}
// Which branch sections of the proposed model apply to one project: the single-cell branch only when the
// project's assay is single-cell (recorded or in text), the flow branch only for flow or the joint goal (#15).
function sectionsFor(p,goal){const tags=E.classify(p).join(' ');const sc=/scRNA|snRNA|single-cell|Fluidigm|ATAC/.test(tags),fl=/flow/i.test(tags)||goal==='joint';return schemas.filter(([n])=>!/scRNA-seq \/ snRNA-seq branch/.test(n)||sc).filter(([n])=>!/Flow cytometry branch/.test(n)||fl);}
const schemas=[
 ['Project, dataset & source record','project_id · dataset_id · source_record_id · original_text · date_type · contact_id','One row per explicitly defined entity. Preserve source file, row, original fields and curator decisions. Resolve repeated titles before merging.'],
 ['Biological material & study design','donor_id / cell_line_id · differentiation_run_id · sample_id · parent_sample_id · condition_id · time_point · biological_replicate_id','Represent biological units before assay observations. Each aliquot points to its parent sample; document human/mouse/ferret and engineered reporters separately.'],
 ['Data resource & processing','file_id · URI/accession · checksum · format · version · access_status · analysis_run_id · software_version · parameters · input/output file IDs','Keep large files externally, with stable references and provenance. A viewer URL is a resource with its own role; it is not automatically a source-data file.'],
 ['scRNA-seq / snRNA-seq branch','library_id → sample_id · cell_id scoped to library · gene_id + namespace/version · matrix_location · layer_semantics · QC · annotation provenance','Keep the matrix in an appropriate external format. Record cells and features in metadata tables (e.g., AnnData obs/var); preserve counts vs processed layers and annotation lineage.'],
 ['Flow cytometry branch','acquisition_id → aliquot/sample_id · panel_id · population_id · parent_population_id · measurement_id · statistic · value · unit · denominator_id · gate/version','Sample → population → measurement → comparison. Percentages require an explicit parent denominator; intensity requires transformation/units. Preserve controls, compensation/unmixing and gating provenance.'],
 ['Comparison & evidence','comparison_id · analysis_unit · group/comparator IDs · replicate IDs · outcome · method/version · evidence_id · reviewer · status','Use the supported biological comparison level. A proposed link, a user-reported link and a verified crosswalk are different evidence states.']
];
function graph(){return `<div class="panel"><div class="panel-title"><h2>One chain for every dataset; the assay comes last</h2>${badge('Proposed model','amber')}</div><p class="hint">Every dataset, whatever the assay, hangs off the same chain: project, then the cell line or donor and its differentiation run, then the sample, then the files. Only the last step differs by assay (a sequencing library or a flow acquisition). Sharing the chain is what lets a flow experiment and a scRNA-seq experiment from the same run be found together. These are proposed entities, not records extracted from the inventory; the small print gives the edge names the graph export uses.</p><div class="map-grid"><div class="entity"><strong>Project</strong>What the inventory already has. <span class="edgenames">IN_LAB · HAS_CONTACT · HAS_ASSAY · USES_ORGANISM</span></div><div class="entity"><strong>Cell line or donor, and the differentiation run</strong>The biological starting point. Today only the reporter description is recorded. <span class="edgenames">USES_REPORTER</span></div><div class="entity"><strong>Sample and aliquot</strong>The physical material each file came from; arrives with the sample sheet. <span class="edgenames">HAS_SAMPLE</span></div><div class="map-connector">Project, then line or run, then sample, then aliquot, then library or acquisition, then results (contrasts, markers, genes)</div><div class="entity rna"><strong>Sequencing branch</strong>Library, then cells and genes, then the matrix and its annotations</div><div class="entity ${state.goal==='joint'?'flow':''}"><strong>${state.goal==='joint'?'Flow branch':state.goal==='share'?'Any other assay':'Flow branch (not needed for this use)'}</strong>${state.goal==='joint'?'Acquisition, then population, then measurement, then comparison':state.goal==='share'?'Files, then the processing record, then the public accession':'Kept in the model; no flow data required for an RNA-only target'}</div><div class="entity"><strong>Evidence</strong>Files, methods, versions, QC, who may reuse it</div><div class="entity wide"><strong>Comparison at the level supported by the evidence</strong>Same sample ≠ same cells. Shared run ≠ paired samples. Condition-only overlap remains explicitly labeled.</div></div></div>`;}
function normPanel(){const t=E.normTable(state.records,state.map,state.norm);const total=Object.values(t).reduce((s,x)=>s+x.length,0);if(!total)return '';return `<div class="panel"><div class="panel-title"><div><h2>Normalisation table</h2><p class="hint" style="margin:5px 0 0">Every distinct source spelling, the proposed controlled term, and who reviewed it. The original string is never changed; the term travels with the graph export as the node name and the source string as evidence on the edge. Target ontologies are noted for the next step; no lookup is performed here.</p></div></div>${Object.entries(t).map(([f,rows])=>`<h3 style="margin-top:18px">${esc(E.NORM_TARGETS[f].label)} <span class="hint">${rows.length} spellings · target namespace ${esc(E.NORM_TARGETS[f].namespace)} (${esc(E.NORM_TARGETS[f].ontology)}) · ${esc(E.NORM_TARGETS[f].biolink)}</span></h3><div class="table-wrap"><table class="norm-table"><thead><tr><th>Source string</th><th>Records</th><th>Controlled term (label now; CURIE in the ${esc(E.NORM_TARGETS[f].namespace)} namespace next)</th><th>Reviewer</th><th>Status</th></tr></thead><tbody>${rows.slice(0,normLimit[f]||12).map(x=>`<tr><td>${esc(x.original)}</td><td class="ev">${x.count}</td><td><input data-norm-field="${f}" data-norm-key="${esc(x.original)}" data-norm-prop="term" value="${esc(x.term)}" placeholder="leave blank if unmapped"></td><td><input data-norm-field="${f}" data-norm-key="${esc(x.original)}" data-norm-prop="reviewer" value="${esc(x.reviewer)}" placeholder="initials"></td><td>${badge(x.status,x.status==='reviewed'?'green':x.status==='proposed'?'amber':'neutral')}</td></tr>`).join('')}</tbody></table></div>${rows.length>(normLimit[f]||12)?`<button class="button quiet" data-norm-more="${f}">Show all ${rows.length}</button>`:''}`).join('')}</div>`;}
const normLimit={};
function mappingTable(){return `<div class="table-wrap"><table class="mapping-table"><thead><tr><th>Current column + example</th><th>Proposed destination</th><th>Concrete transformation / review</th></tr></thead><tbody>${E.MAPPING.map(([k,dest,rule])=>`<tr><td><code>${esc(state.map[k]||'(not mapped)')}</code><p class="hint" style="margin:9px 0 0">${esc(project()[k]||'(blank)')}</p></td><td>${esc(dest)}</td><td>${esc(rule)}</td></tr>`).join('')}</tbody></table></div>`;}
function structure(){if(empty())return emptyPanel();return heading('02 / MAKE THE TARGET CONCRETE','The graph you are working toward.','Keep the source as received. Define the records, identifiers and relationships the knowledge graph needs, then make every proposed transformation reviewable. What LemonAId can export today is the project level of that graph; sample, contrast and gene nodes arrive with the sample-level ingest.')+demoBanner()+context()+graph()+normPanel()+`<div class="panel flush"><div style="padding:23px 23px 10px"><h2>Source-to-target map</h2><p class="hint">${esc(sourceCitation())} • mappings are proposals, not applied transformations.</p></div>${mappingTable()}</div><h2 class="section-heading">Minimum tables and fields to collect</h2><div class="schema-list">${schemas.filter((s,i)=>state.goal==='joint'||i!==4).map(([name,fields,why])=>`<details><summary>${name}</summary><div><p><code>${fields}</code></p><p>${why}</p></div></details>`).join('')}</div><button class="button primary" data-view="connections">Review the missing connections →</button>`;}
function connections(){if(empty())return emptyPanel();const rev=review(),pl=plan();return heading('03 / RESOLVE THE UNKNOWN LINKS','What connects these datasets?','Record what someone has checked, and where that evidence can be found. Answers update the plan; they remain user-reported until the underlying records are reviewed.')+demoBanner()+context()+`<div class="banner blue"><strong>${pl.reported} of ${pl.totalQuestions} questions answered with evidence.</strong> An answer counts once it names a file, a record or a person who confirmed it.</div><div class="panel"><form id="questions-form">${E.applicableQuestions(state.goal).map(q=>{const a=(rev.drafts||rev.answers)[q.id]||{value:'unknown',evidence:''};return `<div class="question"><div class="question-grid"><div><label class="question-title" for="q-${q.id}">${q.label}</label><select id="q-${q.id}" name="${q.id}">${q.options.map(([v,l])=>`<option value="${v}" ${a.value===v?'selected':''}>${l}</option>`).join('')}</select><p class="hint" style="margin-top:8px">${q.why}</p></div><div><label for="e-${q.id}">Evidence / person to confirm</label><textarea id="e-${q.id}" name="e-${q.id}" placeholder="Record a file, crosswalk row, source note or person’s confirmation. Required when changing the answer." maxlength="5000">${esc(a.evidence)}</textarea></div></div></div>`;}).join('')}<div id="question-error" class="error" role="alert"></div><div class="row"><button class="button primary" type="submit">Save answers & update plan →</button><span class="hint">Drafts save locally. Use this button to apply them to the plan.</span></div></form></div>${validationPanel()}<div class="panel"><h2>Optional: paste a file or folder listing</h2><p class="hint">Names help identify files to request. They do not establish contents, matrix meaning, permissions or sample links. This prototype does not read these file paths.</p><label for="file-list">File paths / descriptions</label><textarea id="file-list" rows="5" placeholder="project/sample_metadata.csv&#10;project/processed_object.h5ad&#10;project/flow/sample01.fcs">${esc(rev.files)}</textarea><button class="button" id="save-files" style="margin-top:12px">Save file pointers</button><div class="file-hints" id="file-hints"></div></div>`;}
function validationPanel(){const v=review().validation||{sheet:'',listing:'',excluded:'',ran:''};let result=null,error='';if(v.ran&&v.sheet&&v.listing){try{result=E.validateSampleSheet(v.sheet,v.listing,{excludedText:v.excluded});}catch(e){error=e.message;}}
 const st=s=>badge(s.replace('_',' '),s==='pass'?'green':s==='fail'?'amber':'neutral');
 return `<div class="panel"><div class="panel-title"><div><h2>Validate a sample sheet</h2><p class="hint" style="margin:5px 0 0">The first step from planning to checking. Paste the project's sample sheet and a listing of its files (the output of <code>find . -type f</code>, or any one-path-per-line list). Every row gets pass, fail, recoverable, unknown or not applicable, with a repair and an owner. Nothing is changed. The command-line version, <code>tools/validate_samplesheet.cjs</code>, walks the real folder and can verify checksums.</p></div></div><div class="vgrid"><div><label for="v-sheet">Sample sheet (CSV or TSV, header row)</label><textarea id="v-sheet" rows="6" placeholder="sample_id&#9;condition&#9;file&#10;S01&#9;control&#9;raw/S01.fcs">${esc(v.sheet)}</textarea></div><div><label for="v-listing">File listing, one path per line</label><textarea id="v-listing" rows="6" placeholder="raw/S01.fcs&#10;raw/S02.fcs">${esc(v.listing)}</textarea></div></div><label for="v-excluded" style="margin-top:12px">Exclusion list (optional; first column is the sample ID or filename, last column the reason)</label><textarea id="v-excluded" rows="2">${esc(v.excluded)}</textarea><label for="v-panel" style="margin-top:12px">Panel manifest (optional; the panel_manifest.csv that <code>tools/fcs_panel_manifest.py</code> writes from the FCS headers)</label><textarea id="v-panel" rows="2" placeholder="file,detector,stain_label,match,reagent_ids,inventory_conjugate">${esc(v.panel||'')}</textarea>${v.panel?`<p class="hint">${E.parseManifest(v.panel).length} stained channels across ${new Set(E.parseManifest(v.panel).map(x=>x.file)).size} files will be exported as DataFile and Reagent nodes with STAINED_WITH edges. Reagent inventory loaded: ${R.length} entries.</p>`:`<p class="hint">Reagent inventory loaded: ${R.length} entries from the EpiFlow Panel Builder; they join the graph export once a manifest links files to them.</p>`}<div class="row" style="margin-top:12px"><button class="button primary" id="v-run">Validate</button><label class="filebox" style="margin:0;padding:8px 12px;font-size:12px">Or choose files: sheet <input type="file" id="v-sheet-file" accept=".csv,.tsv,.txt"> listing <input type="file" id="v-listing-file" accept=".txt,.csv,.tsv"></label></div>${error?`<p class="error">${esc(error)}</p>`:''}${result?validationResult(result):''}</div>`;}
function validationResult(r){const c=r.summary.counts;const bad=r.rows.filter(x=>x.checks.some(k=>!['pass','not_applicable'].includes(k.status)));return `<div class="vresult"><div class="stats" style="margin:18px 0 10px"><div class="stat"><strong>${r.rows.length}</strong><span>samples<br>${r.columns.files.length?'file column: '+esc(r.columns.files.join(', ')):'no file column'}</span></div><div class="stat"><strong>${c.pass||0}</strong><span>checks pass<br>${c.recoverable||0} recoverable · ${c.fail||0} fail · ${c.unknown||0} unknown</span></div><div class="stat"><strong>${r.orphans.length}</strong><span>data files no sample names<br>${r.summary.derived||0} derived files credited</span></div><div class="stat"><strong>${r.replicates.filter(x=>x.status==='fail').length}</strong><span>conditions with n = 1<br>of ${r.replicates.length} conditions</span></div></div>${r.sheet.notes.length?`<p class="hint">Notes kept from the sheet, not parsed as samples: ${r.sheet.notes.map(esc).join('; ')}</p>`:''}<p class="hint">Columns read as: ID <code>${esc(r.columns.id)}</code>; design ${r.columns.design.map(x=>'<code>'+esc(x)+'</code>').join(', ')||'none'}; control ${r.columns.control?'<code>'+esc(r.columns.control)+'</code>':'inferred from names'}.</p><h3 style="margin-top:16px">Replicates per condition</h3><div class="table-wrap"><table><thead><tr><th>Condition</th><th>n</th><th>Status</th></tr></thead><tbody>${r.replicates.map(x=>`<tr><td>${esc(x.condition)}</td><td class="ev">${x.n}</td><td>${st(x.status)} <span class="hint">${esc(x.reason)}</span></td></tr>`).join('')}</tbody></table></div><h3 style="margin-top:16px">Findings (${bad.length} of ${r.rows.length} samples)</h3>${bad.length?`<div class="table-wrap"><table><thead><tr><th>Sample</th><th>Check</th><th>Status</th><th>Reason and repair</th></tr></thead><tbody>${bad.flatMap(x=>x.checks.filter(k=>!['pass','not_applicable'].includes(k.status)).map(k=>`<tr><td>${esc(x.id)}<span class="source-id">row ${x.row}</span></td><td>${esc(k.check)}</td><td>${st(k.status)}</td><td>${esc(k.reason)}${k.repair?`<br><span class="hint">Repair: ${esc(k.repair)}${k.owner?' · '+esc(k.owner):''}</span>`:''}</td></tr>`)).join('')}</tbody></table></div>`:'<p class="hint">Every sample passes identity, file and design checks.</p>'}${r.orphans.length?`<h3 style="margin-top:16px">Data files on disk that no sample names</h3><p class="hint">${r.orphans.slice(0,30).map(esc).join('<br>')}${r.orphans.length>30?'<br>… '+(r.orphans.length-30)+' more':''}</p>`:''}<h3 style="margin-top:16px">Actions</h3><ol class="step-list">${r.actions.map(x=>`<li><strong>${esc(x.title)}</strong> <span class="hint">${esc(x.owner)} · done when: ${esc(x.done)}</span></li>`).join('')}</ol><p class="hint">When the findings are resolved, record the outcome as evidence under “Can libraries and acquisitions be traced to samples and runs?” above; the validator does not answer that question for you.</p><button class="button" id="export-validation" style="margin-top:8px">Export these checks (CSV) ↗</button></div>`;}
const st=s=>badge(s.replace('_',' '),s==='pass'?'green':s==='fail'?'amber':'neutral');
function saveDraft(){review().drafts=Object.fromEntries(E.applicableQuestions(state.goal).map(q=>[q.id,{value:$('#q-'+q.id).value,evidence:$('#e-'+q.id).value}]));persist();}
function fileHints(){const t=review().files;const types=[[/\.fcs\b/i,'FCS filename: request acquisition and gating context'],[/\.h5ad\b/i,'AnnData filename: inspect obs / var / layer semantics'],[/\.rds\b/i,'R object filename: confirm object type and provenance'],[/\.mtx\b|\.h5\b/i,'Matrix filename: confirm dimensions and representation'],[/\.tiff?\b|\.png\b|\.jpe?g\b/i,'Image pointer: future extension; content not interpreted'],[/\.pdf\b|\.docx\b/i,'Document pointer: future protocol review']].filter(([re])=>re.test(t));$('#file-hints').innerHTML=types.map(([,s])=>badge(s,'neutral')).join('')+(t&&!types.length?'<span class="hint">Pointers saved. Ask the custodian to describe the files and their sample relationships.</span>':'');}
function actionCards(pl){return pl.actions.map((a,i)=>`<details class="action" ${i===0?'open':''}><summary><span class="action-number">${String(i+1).padStart(2,'0')}</span><span class="action-title">${esc(a.title)}<span class="action-meta">Suggested role: ${esc(a.owner)} · ${a.depends.length?a.depends.length+' active prerequisite(s)':'can begin now'}</span></span>${badge(a.priority,a.priority.startsWith('1')?'amber':'neutral')}</summary><div class="action-body"><p>${esc(a.why)}</p><dl><dt>Deliverable</dt><dd>${esc(a.deliverable)}</dd><dt>Done when</dt><dd>${esc(a.check)}</dd><dt>Depends on</dt><dd>${a.depends.length?a.depends.map(id=>esc(pl.actions.find(x=>x.id===id)?.title||id)).join('; '):'No active prerequisite; work can begin now.'}</dd><dt>Evidence basis</dt><dd>${esc(sourceCitation())}, plus the answers recorded under Connections to confirm.</dd></dl><label for="owner-${a.id}">Assigned owner (optional)</label><input id="owner-${a.id}" data-owner="${a.id}" value="${esc(review().owners[a.id]||'')}" placeholder="Name / role — this does not send a message"><label for="note-${a.id}">Progress / decision notes</label><textarea id="note-${a.id}" data-note="${a.id}" rows="2" placeholder="Record work completed, an exception or the next person to consult.">${esc(review().notes[a.id]||'')}</textarea><p class="hint" style="margin:8px 0 0">Notes save as you type. Resolve a question under Connections to confirm to update its action.</p></div></details>`).join('');}
function actions(){if(empty())return emptyPanel();const pl=plan();return heading('04 / TURN GAPS INTO WORK','Your preparation plan.','An ordered list of concrete next steps, grounded in the inventory and the evidence you have recorded. Resolve prerequisites before treating downstream work as complete.')+demoBanner()+context()+`<div class="banner ${pl.blockers.length?'':'blue'}"><strong>${esc(pl.status)}.</strong> ${pl.blockers.length?esc(pl.blockers.join(' · '))+'.':'The last action, validating the files, stays open until someone has opened them.'}</div><div class="panel"><div class="panel-title"><div class="readiness"><strong>${pl.actions.length}</strong><p>open actions<br><span class="hint">${pl.reported}/${pl.totalQuestions} questions answered with evidence</span></p></div><button class="button" data-view="connections">Update evidence</button></div></div>${actionCards(pl)}<div class="panel"><h3>What a usable handoff contains</h3><p class="hint">Source inventory + proposed schema + source-to-target map + evidence register + ordered actions + reviewed validation results. Large matrices, FCS files and images remain in their appropriate storage.</p><button class="button primary" id="export-inline">Export this plan ↗</button></div>`;}
function future(){return heading('LATER / EXTEND THE MODEL','Protocols and Western blots fit here.','Plan the connections now. Add document and image ingestion only after the shared sample, run, file and provenance model has been tested with flow and single-cell RNA data.')+`<div class="banner"><strong>Future scope only.</strong> No protocol extraction, image interpretation, band detection or densitometry is implemented in this prototype.</div><div class="future-grid"><div class="panel"><div class="eyebrow">DOCUMENTS → EXECUTED METHODS</div><h2>Protocols</h2><div class="flow-path"><span>Protocol version</span><b>→</b><span>Step</span><b>→</b><span>Execution</span><b>→</b><span>Run / sample</span></div><ul class="step-list"><li>Register the original document, version, author and effective date.</li><li>Propose steps, reagents, concentrations, duration, equipment and critical parameters for review.</li><li>Separate the intended protocol from what was actually performed, including deviations.</li><li>Link a documented execution to the run and samples it produced or processed.</li><li>Preserve page/section evidence for every extracted claim.</li></ul><h3>First demonstration</h3><p class="hint">Compare two protocol versions and identify which run metadata must be recovered to interpret differences in flow outcomes and RNA profiles.</p><h3>Acceptance check</h3><p class="hint">A scientist verifies extracted steps, units and execution links; missing or conflicting conditions stay unresolved.</p></div><div class="panel"><div class="eyebrow">IMAGES → TRACEABLE MEASUREMENTS</div><h2>Western blot images</h2><div class="flow-path"><span>Original image</span><b>→</b><span>Lane</span><b>→</b><span>Sample</span><b>→</b><span>Measurement</span></div><ul class="step-list"><li>Register uncropped source images and file checksums; preserve exposure/acquisition metadata.</li><li>Obtain lane-to-sample maps, molecular-weight markers, targets, antibody identifiers and controls.</li><li>Record crop/processing lineage separately from the original image.</li><li>If quantification is later added, document regions, background correction, saturation checks, normalization and replicate definitions.</li><li>Flag missing context before proposing any comparison.</li></ul><h3>First demonstration</h3><p class="hint">Turn an image plus lane sheet into a list of missing metadata and a proposed evidence map. Do not infer sample identity from appearance.</p><h3>Acceptance check</h3><p class="hint">A reviewer can trace each reported value to the original image region, sample, processing method and valid control.</p></div></div><div class="panel"><h2>Build in three stages</h2><ol class="step-list"><li><strong>Now:</strong> inventory intake, flow/scRNA-seq schema, questions and actionable handoff.</li><li><strong>Next:</strong> validate real sample manifests and file metadata, with explicit permission and an agreed pilot dataset.</li><li><strong>Later:</strong> add protocol and image adapters using the same evidence and review model; test extraction against scientist-curated examples.</li></ol><p class="hint">Automated transformations and model-assisted extraction need separate validation. This version uses transparent rules and keeps every proposed mapping reviewable.</p></div><div class="panel"><h2>Reference points for the next version</h2><ul class="resource-list"><li><a href="https://anndata.readthedocs.io/en/stable/generated/anndata.AnnData.html" target="_blank" rel="noopener noreferrer">AnnData: annotated matrix, observations and variables</a></li><li><a href="https://github.com/chanzuckerberg/single-cell-curation/blob/main/schema/7.0.0/schema.md" target="_blank" rel="noopener noreferrer">CELLxGENE schema 7.0.0: a reference for single-cell metadata requirements</a> — version-specific; this prototype does not validate against it.</li><li><a href="https://doi.org/10.1002/cyto.a.20623" target="_blank" rel="noopener noreferrer">MIFlowCyt: minimum information about a flow cytometry experiment</a></li><li><a href="https://www.w3.org/TR/prov-o/" target="_blank" rel="noopener noreferrer">W3C PROV-O: provenance relationships</a></li><li><a href="https://linkml.io/linkml/" target="_blank" rel="noopener noreferrer">LinkML: an option for expressing and validating the future schema</a></li></ul></div>`;}
function render(){
 $('#source-name').textContent=sourceLabel();$('#brand-name').innerHTML=BRAND.name==='LemonAId'?'Lemon<b>AI</b>d':esc(BRAND.name);$('#brand-sub').textContent=BRAND.sub;$$('.sidebar [data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===state.view);if(b.dataset.view===state.view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});
 $('#content').innerHTML=({inventory,structure,connections,actions,future}[state.view]||inventory)();
 if(state.view==='inventory')renderRows();if(state.view==='connections')fileHints();persist();
}
function resetRegistry(){const n=Object.values(state.reviews).filter(r=>Object.keys(r.answers||{}).length||Object.values(r.notes||{}).some(Boolean)).length;if(!confirm(`Return to the embedded registry? This discards the current session in this browser${n?`, including evidence or notes on ${n} project${n>1?'s':''}`:''}${state.lastExport?` (last exported ${ago(state.lastExport).replace('exported ','')})`:' (never exported)'}. Export a session first if you want to keep them.`))return;state=fresh();search='';filter='all';labFilter='all';render();toast('Registry restored.');}
function loadDemo(which='recover'){
 const evidence='ILLUSTRATIVE ONLY — fictional teaching notes, not an observation about a lab project.';
 const answers={rna:{value:'yes',evidence:evidence+' Matrix and sample sheet located at demo/rna/.'},flow:{value:'yes',evidence:evidence+' FCS files and gates located at demo/flow/.'},samples:{value:'recover',evidence:evidence+' Run notebook exists; aliases still need reconciliation.'},relation:{value:'run',evidence:evidence+' Shared run documented; aliquot pairing is not yet known.'}};
 if(which==='partial'){answers.samples={value:'unknown',evidence:''};answers.matrix={value:'counts',evidence:evidence+' Processing log describes integer UMI counts.'};}
 if(which==='blocked')answers.samples={value:'no',evidence:evidence+' No crosswalk or recoverable identifiers remain.'};
 const raw={project_id:'DEMO-LUNG-001',Dataset_Name:'Teaching example: lung differentiation, flow + scRNA-seq',lab:'Teaching example',project_date:'Illustrative date',experiment_type:'10x scRNA-seq + spectral flow (illustrative)',geo_accession:'NA',contact_person:'Illustrative scientist',genome_reference:'Human / hg38 (verify)',reporters:'Lineage reporter A-GFP; marker B-tdTomato (illustrative)',purpose_of_experiment:'FICTIONAL: compare control and treatment across independent differentiation runs, using reporter-positive flow populations and scRNA-seq cell-state profiles. No actual sample numbers or outcomes are claimed.',analysis_visualization_link:'NA',shinyapp_link:'NA'};
 state={version:1,scenario:which,source:{name:'Fictional teaching fixture',mode:'demo',records:1},records:[{key:'demo-1',row:2,raw}],map:{...E.DEFAULT_MAP},selected:'demo-1',goal:'joint',view:'connections',reviews:{'demo-1':{answers,files:'demo/rna/processed_object.h5ad\ndemo/flow/run01.fcs\ndemo/metadata/run_notes.csv',owners:{},notes:{}}}};search='';filter='all';labFilter='all';render();toast('Fictional example loaded. Real inventory remains in the original files.');
}
function intakeStep(n){const steps=$$('#intake-dialog .steps li');steps.forEach(li=>{const k=Number(li.dataset.step);li.className=k===n?'current':k<n?'done':'';});const s1=$('#intake-step-1');if(s1)s1.hidden=n!==1;}
function showMapping(parsed,name,intro){
 pending={...parsed,name,map:E.suggestMap(parsed.headers)};$('#import-error').textContent='';intakeStep(2);
 $('#mapping-preview').innerHTML=`<h3 style="margin-top:8px">${esc(name)}: ${parsed.rows.length} projects, ${parsed.headers.length} columns</h3>${intro?`<p class="hint">${esc(intro)}</p>`:''}<p>For each thing LemonAId tracks, pick the column in your file that holds it. Skip anything you do not have; it becomes a gap to fill later. Your values are never changed.</p><div class="mapping-grid">${E.FIELDS.map(([k,label])=>`<label for="map-${k}">${label}</label><select id="map-${k}" data-map="${k}"><option value="">I do not have this column</option>${parsed.headers.map(h=>`<option value="${esc(h)}" ${pending.map[k]===h?'selected':''}>${esc(h)}</option>`).join('')}</select>`).join('')}</div><div class="mapping-actions"><button id="intake-back" class="button quiet">Back</button><button id="intake-check" class="button primary">Next: check and import</button></div>`;
}
function showCheck(){
 if(!pending)return;intakeStep(3);const map=pending.map,sample=pending.rows.slice(0,3).map(r=>E.canonical(r,map));
 const unmapped=E.FIELDS.filter(([k])=>!map[k]).map(([,l])=>l);const mapped=E.FIELDS.filter(([k])=>map[k]);
 $('#mapping-preview').innerHTML=`<h3 style="margin-top:8px">Check before importing</h3><p>${pending.rows.length} projects will be imported from <strong>${esc(pending.name)}</strong>. ${mapped.length} of ${E.FIELDS.length} planning fields are matched${unmapped.length?`; not supplied: ${esc(unmapped.join(', '))}`:''}.</p><div class="table-wrap"><table><thead><tr>${mapped.map(([,l])=>`<th>${esc(l)}</th>`).join('')}</tr></thead><tbody>${sample.map(p=>`<tr>${mapped.map(([k])=>`<td>${esc(String(p[k]||'').slice(0,60))}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="hint">First ${sample.length} of ${pending.rows.length}, as LemonAId will read them.</p>${state.records.length?'<div class="banner blue">Importing replaces the inventory and notes in this browser. Export a session first if you want to keep them.</div>':''}<div class="mapping-actions"><button id="intake-back-2" class="button quiet">Back to matching</button><button id="commit-intake" class="button primary">Import these ${pending.rows.length} projects</button></div>`;
}
function parseIntake(text,name){try{showMapping(E.parseDelimited(text),name);}catch(e){pending=null;$('#mapping-preview').innerHTML='';intakeStep(1);$('#import-error').textContent=e.message;}}
// Folder door: list what the browser hands us, read only README and notebook text, build the inventory in the engine.
const TEXT_LIMIT=200_000;
async function intakeFolder(fileList){
 const files=[...fileList];const prog=$('#folder-progress');if(!files.length){prog.textContent='That folder appears to be empty.';return;}
 prog.textContent=`Listing ${files.length.toLocaleString()} files…`;
 const entries=[];let readCount=0;
 for(const f of files){const path=f.webkitRelativePath||f.name;const base=path.split('/').pop();let text=null;
  if(/^readme(\.(md|txt|rst))?$/i.test(base)||/\.(qmd|rmd|ipynb)$/i.test(base)){if(f.size<=TEXT_LIMIT){try{text=await f.text();readCount++;}catch{text=null;}}}
  entries.push({path,size:f.size,modified:f.lastModified,text});}
 const inv=E.inventoryFromFolder(entries);
 const rootName=(files[0].webkitRelativePath||'').split('/')[0]||'folder';
 prog.textContent=`Read ${files.length.toLocaleString()} file names in ${inv.projects} project folders; opened ${readCount} README or notebook files for their titles. No other file was opened.`;
 if(!inv.projects){$('#import-error').textContent='No project folders found. Choose the folder that contains one folder per project.';return;}
 showMapping(inv,'Folder: '+rootName,'Every value below was guessed from names, dates and README text and is marked as inferred. The column matching is already set; check it, then review the projects.');
}
function stamp(){state.lastExport=new Date().toISOString();persist();}
// Every export says what it is: an alpha whose identifiers will change when the center's identifier prefixes land.
const ALPHA_NOTE=`LemonAId ${VERSION}, alpha: identifiers and column names may change before v1.0; do not build pipelines on them yet.`;
function stamped(name,text){if(/\.csv$/.test(name))return text.replace(/\r?\n$/,'')+'\n# '+ALPHA_NOTE+'\n';if(/\.html$/.test(name))return text.replace('</html>',`<p class="hint">${esc(ALPHA_NOTE)}</p></html>`);if(/\.json$/.test(name)){try{const o=JSON.parse(text);o.alpha_note=ALPHA_NOTE;return JSON.stringify(o);}catch{return text;}}return text;}
function download(name,text,type){text=stamped(name,text);$('#export-result').hidden=false;$('#export-filename').textContent='Prepared: '+name;$('#export-text').value=text;const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('Download prepared: '+name);stamp();}
function derivedRows(){const total=E.applicableQuestions(state.goal).length;return state.records.map(r=>{const p=E.canonical(r,state.map),sp=E.species(p),rd=E.readiness(p);return [p.project_id,p.Dataset_Name,labOf(r),p.project_date,p.contact_person,p.experiment_type,E.classify(p).join('; '),p.genome_reference,sp.organism,reach(p)[0],p.geo_accession,p.shinyapp_link,p.analysis_visualization_link,rd.score,rd.shared?'':rd.next,evidenceCount(r.key)+'/'+total,r.row];});}
function overviewHTML(){const c=E.completeness(state.records,state.map),n=c.n||1,labels=Object.fromEntries(E.FIELDS);const all=state.records.map(r=>E.canonical(r,state.map));const byLab=new Map();for(const r of state.records){const l=labOf(r),p=E.canonical(r,state.map),k=reach(p)[0];if(!byLab.has(l))byLab.set(l,{n:0,'Public accession':0,'Viewer only':0,'Local only':0});byLab.get(l).n++;byLab.get(l)[k]++;}const list=E.shortlist(state.records,state.map,10,state.reviews);const tieNote=list.tied>1?` ${list.tied} of ${list.total} projects share the top score of ${list.top}/8; ${E.SHORTLIST_TIEBREAK}`:'';return `<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>LemonAId inventory overview, ${esc(sourceLabel())}</title><style>body{max-width:900px;margin:45px auto;padding:0 25px;color:#1f3a31;font:15px/1.6 system-ui}h1{font-family:'Avenir Next',system-ui;font-weight:500;font-size:32px;margin-bottom:4px;color:#173E32}h2{margin-top:38px;font-size:20px}table{width:100%;border-collapse:collapse;font-size:13px}th,td{border-bottom:1px solid #dce1e7;text-align:left;vertical-align:top;padding:9px 10px}th{color:#647180;font-size:11px;text-transform:uppercase;letter-spacing:.5px}td.num{text-align:right;font-variant-numeric:tabular-nums}.hint{color:#5d6c7b;font-size:13px}.bar{height:8px;background:#eceff2;border-radius:4px}.bar i{display:block;height:100%;background:#173E32;border-radius:4px}.stats{display:flex;gap:28px;margin:22px 0}.stats div{flex:1}.stats strong{display:block;font:34px Georgia,serif}@media print{body{margin:0}}</style><h1>Inventory overview</h1><p class="hint">${esc(sourceLabel())} · ${state.records.length} records · exported ${esc(new Date().toISOString().slice(0,10))}. Coverage of the inventory as received; nothing here is a check of the files behind it.</p><div class="stats"><div><strong>${state.records.length}</strong>project records</div><div><strong>${c.geo}</strong>with a public accession</div><div><strong>${all.filter(p=>reach(p)[0]==='Viewer only').length}</strong>viewer only</div><div><strong>${all.filter(p=>reach(p)[0]==='Local only').length}</strong>local only</div></div><p class="hint">Reach is the most public place the inventory records for a dataset. ${Object.entries(REACH_DEF).map(([k,v])=>`<em>${k}</em>: ${v}`).join(' ')}</p><h2>What the inventory records</h2><table>${E.READINESS_FIELDS.map(f=>[labels[f],c.fields[f]]).sort((x,y)=>y[1]-x[1]).map(([l,v])=>`<tr><td style="width:220px">${esc(l)}</td><td><div class="bar"><i style="width:${Math.round(100*v/n)}%"></i></div></td><td class="num" style="width:60px">${Math.round(100*v/n)}%</td></tr>`).join('')}</table><h2>Reach by laboratory</h2><table><tr><th>Laboratory</th><th>Records</th><th>Public accession</th><th>Viewer only</th><th>Local only</th></tr>${[...byLab.entries()].sort((x,y)=>y[1].n-x[1].n).map(([l,v])=>`<tr><td>${esc(l)}</td><td class="num">${v.n}</td><td class="num">${v['Public accession']}</td><td class="num">${v['Viewer only']}</td><td class="num">${v['Local only']}</td></tr>`).join('')}</table><h2>Closest to shareable, by what the inventory records</h2><p class="hint">${esc(E.READINESS_RULE)}${esc(tieNote)}</p><table><tr><th>#</th><th>Project</th><th>Laboratory</th><th>Recorded</th><th>Needs next</th></tr>${list.map((x,i)=>`<tr><td>${i+1}</td><td>${esc(E.missing(x.p.Dataset_Name)?x.p.project_id:x.p.Dataset_Name)}<br><span class="hint">${esc(x.p.project_id)}</span></td><td>${esc(labOf(x.record))}</td><td class="num">${x.score}/8</td><td>${esc(x.next)}</td></tr>`).join('')}</table><p class="hint" style="margin-top:40px">Generated by LemonAId ${esc(VERSION)}. © 2026 Center for Regenerative Medicine, Boston University. Reach is the most public place the inventory records for a dataset; a viewer link is not a repository.</p></html>`;}
function slug(){return (project().project_id||'project').replace(/[^a-z0-9_-]/ig,'_');}
function reportHTML(){const pl=plan(),rev=review();return `<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>LemonAId preparation plan, ${esc(title())}</title><style>body{max-width:1050px;margin:45px auto;padding:0 25px;color:#1f3a31;font:14px/1.6 system-ui}h1{font-family:'Avenir Next',system-ui;font-weight:500;font-size:34px;color:#173E32}h2{margin-top:35px}table{width:100%;border-collapse:collapse;font-size:12px}th,td{border:1px solid #dce1e7;text-align:left;vertical-align:top;padding:12px;overflow-wrap:anywhere}th{background:#f1f4f7}section{border-top:1px solid #ddd;margin-top:20px;padding-top:14px}.hint{font-size:12px;color:#5d6c7b}code{font-size:11px}.badge{display:inline-block;padding:3px 7px;background:#eef2f6;margin:3px}.facts div{padding:7px;border-top:1px solid #eee}.facts dt{font-weight:bold}.facts dd{margin:0}a{color:#2c5b48}@media print{body{margin:0;max-width:none}section{break-inside:avoid}}</style><h1>LemonAId preparation plan</h1><p><strong>${esc(title())}</strong><br>${esc(sourceLabel())} • exported ${esc(new Date().toISOString())}</p><p><strong>Intended use:</strong> ${esc(goalLabel(state.goal))}<br><strong>Status:</strong> ${esc(pl.status)}. ${pl.reported}/${pl.totalQuestions} questions answered with evidence.</p><p>This report contains the inventory text as received, the proposed structure and the evidence people recorded. No assay files have been inspected or validated by the planner itself. ${state.source.mode==='demo'?'ALL SOURCE RECORDS AND EVIDENCE IN THIS SESSION ARE FICTIONAL.':''}</p><h2>Source and preservation</h2><p>${esc(sourceCitation())}<br>Source path: ${esc(state.source.path||'not recorded')}<br>Source SHA-256: ${esc(state.source.sha256||'not recorded')}</p>${sourceDetails()}<h2>Proposed source-to-target map</h2>${mappingTable()}<h2>Proposed tables</h2>${sectionsFor(E.canonical(record(),state.map),state.goal).map(([n,f,w])=>`<section><h3>${n}</h3><p><code>${f}</code></p><p>${w}</p></section>`).join('')}<h2>Planning questions and evidence</h2><table><tr><th>Question</th><th>Reported answer</th><th>Evidence note</th></tr>${E.applicableQuestions(state.goal).map(q=>{const a=rev.answers[q.id];return `<tr><td>${q.label}</td><td>${esc(q.options.find(x=>x[0]===E.answer(rev.answers,q.id))?.[1]||'Not yet checked')}</td><td>${esc(a?.evidence||'None supplied')}</td></tr>`;}).join('')}</table><h2>File pointers (not inspected)</h2><pre style="white-space:pre-wrap">${esc(rev.files||'None supplied')}</pre><h2>Ordered action plan</h2>${pl.actions.map((a,i)=>`<section><h3>${i+1}. ${esc(a.title)} — ${esc(a.priority)}</h3><p>${esc(a.why)}</p><p><strong>Owner:</strong> ${esc(rev.owners[a.id]||a.owner+' (suggested role)')}<br><strong>Deliverable:</strong> ${esc(a.deliverable)}<br><strong>Done when:</strong> ${esc(a.check)}<br><strong>Prerequisites:</strong> ${esc(a.depends.map(id=>pl.actions.find(x=>x.id===id)?.title||id).join('; ')||'None active')}<br><strong>Progress note:</strong> ${esc(rev.notes[a.id]||'None recorded')}</p></section>`).join('')}<h2>Scope and next extensions</h2><p>Protocols and Western blots are planned extensions only. Protocol version → step → execution → run/sample; original blot image → lane → sample → measurement, with processing and control provenance. Document extraction, image quantification and automated transformation are not implemented.</p><p>Standards to consult: <a href="https://anndata.readthedocs.io/en/stable/generated/anndata.AnnData.html">AnnData</a>; <a href="https://github.com/chanzuckerberg/single-cell-curation/blob/main/schema/7.0.0/schema.md">CELLxGENE schema 7.0.0</a>; <a href="https://doi.org/10.1002/cyto.a.20623">MIFlowCyt</a>; <a href="https://www.w3.org/TR/prov-o/">PROV-O</a>. No conformance is claimed. Generated by LemonAId ${esc(VERSION)}.</p></html>`;}
document.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b)return;
 if(b.dataset.view){navigate(b.dataset.view);return;}if(b.dataset.close){$('#'+b.dataset.close).close();return;}
 if(b.dataset.sort){sortBy=sortBy===b.dataset.sort?'row':b.dataset.sort;render();return;}
 if(b.dataset.project){state.selected=b.dataset.project;render();$('#project-select').scrollIntoView({block:'center',behavior:'smooth'});return;}
 const id=b.id;
 if(id==='import-open')$('#intake-dialog').showModal();
 if(id==='export-open'||id==='export-inline')$('#export-dialog').showModal();
 if(id==='parse-intake')parseIntake($('#paste-data').value,'Pasted inventory');
 if(id==='intake-back'){pending=null;$('#mapping-preview').innerHTML='';$('#import-error').textContent='';intakeStep(1);}
 if(id==='intake-back-2'&&pending)showMapping({headers:pending.headers,rows:pending.rows,delimiter:pending.delimiter},pending.name);
 if(id==='intake-check'&&pending){for(const sel of $$('#mapping-preview select[data-map]'))pending.map[sel.dataset.map]=sel.value;showCheck();}
 if(id==='download-template')download('project_inventory_template.csv',E.templateCSV(),'text/csv;charset=utf-8');
 if(id==='download-guide')download('project_inventory_template_guide.md',E.templateGuideMarkdown(),'text/markdown;charset=utf-8');
 if(id==='load-example'){const csv=window.LEMONAID_EXAMPLE||'';if(!csv){$('#import-error').textContent='The example inventory is not included in this build.';return;}const parsed=E.parseDelimited(csv);const map=E.suggestMap(parsed.headers);state={version:1,source:{name:'Example inventory (Serrano Lab, 21 October 2026)',mode:'import',records:parsed.rows.length},records:parsed.rows,map,selected:parsed.rows[0].key,goal:'share',reviews:{},view:'inventory'};search='';filter='all';labFilter='all';pending=null;if($('#intake-dialog').open)$('#intake-dialog').close();render();toast('Example inventory loaded: 49 real projects from one lab, as scanned from its folders.');}
 if(id==='commit-intake'&&pending){for(const sel of $$('#mapping-preview select[data-map]'))pending.map[sel.dataset.map]=sel.value;state={version:1,source:{name:pending.name,mode:'import',records:pending.rows.length},records:pending.rows,map:pending.map,selected:pending.rows[0].key,goal:'share',reviews:{},view:'inventory'};search='';filter='all';labFilter='all';pending=null;$('#intake-dialog').close();$('#mapping-preview').innerHTML='';intakeStep(1);render();toast('Inventory imported. Original values preserved.');}
 if(id==='load-demo'){if(Object.keys(state.reviews).some(k=>Object.keys(state.reviews[k].answers||{}).length)&&!confirm('Switch to a fictional example? Export this session first to retain your current review notes.'))return;loadDemo();}
 if(id==='apply-demo'){loadDemo($('#demo-case').value);}
 if(id==='restore-registry')resetRegistry();
 if(id==='v-run'){const rev=review();rev.validation={sheet:$('#v-sheet').value,listing:$('#v-listing').value,excluded:$('#v-excluded').value,panel:$('#v-panel').value,ran:new Date().toISOString()};persist();render();toast('Sample sheet checked against the listing.');return;}
 if(id==='export-validation'){const v=review().validation;const r=E.validateSampleSheet(v.sheet,v.listing,{excludedText:v.excluded});download(slug()+'-samplesheet-checks.csv',E.csv([['Row','Sample ID','Check','Status','Reason','Repair','Owner','Done when'],...r.rows.flatMap(x=>x.checks.map(k=>[x.row,x.id,k.check,k.status,k.reason,k.repair,k.owner,k.done]))]),'text/csv;charset=utf-8');return;}
 if(id==='save-files'){review().files=$('#file-list').value;persist();fileHints();toast('File pointers saved; paths have not been inspected.');}
 if(id==='export-session'){dirtySinceExport=false;download('lemonaid-session.json',JSON.stringify({...state,lemonaid_version:VERSION,exportedAt:new Date().toISOString()},null,2),'application/json');}
 if(id==='export-actions'){const pl=plan();download(slug()+'-actions.csv',E.csv([['Order','Action ID','Priority','Title','Reason','Deliverable','Assigned or suggested owner','Depends on action IDs','Done when','Progress note','Source','Evidence status'],...pl.actions.map((a,i)=>[i+1,a.id,a.priority,a.title,a.why,a.deliverable,review().owners[a.id]||a.owner+' (suggested)',a.depends.join('; '),a.check,review().notes[a.id]||'',sourceCitation(),'Proposed plan; user-reported evidence; assay files unvalidated'])]),'text/csv;charset=utf-8');}
 if(id==='export-report')download(slug()+'-preparation-plan.html',reportHTML(),'text/html;charset=utf-8');
 if(id==='export-overview')download('inventory-overview.html',overviewHTML(),'text/html;charset=utf-8');
 if(id==='export-nodes'||id==='export-edges'){const g=E.graphExport(state.records,state.map,state.pmap||{},state.reviews,E.normTable(state.records,state.map,state.norm),R,{sourceName:state.source.name||'inventory'});if(id==='export-nodes'){const keys=[...new Set(g.nodes.flatMap(n=>Object.keys(n)))];download('graph-nodes.csv',E.csv([keys,...g.nodes.map(n=>keys.map(k=>n[k]??''))]),'text/csv;charset=utf-8');}else download('graph-edges.csv',E.csv([['source','relation','target','provenance','knowledge_level','agent_type','primary_knowledge_source','source_record','evidence'],...g.edges.map(e=>[e.source,e.relation,e.target,e.provenance,e.knowledge_level,e.agent_type,e.primary_knowledge_source,e.source_record,e.evidence])]),'text/csv;charset=utf-8');}
 if(id==='export-norm'){const t=E.normTable(state.records,state.map,state.norm);download('normalisation-table.csv',E.csv([['Field','Target ontology','Source string','Records','Controlled term','Reviewer','Status'],...Object.entries(t).flatMap(([f,rows])=>rows.map(x=>[E.NORM_TARGETS[f].label,E.NORM_TARGETS[f].ontology,x.original,x.count,x.term,x.reviewer,x.status]))]),'text/csv;charset=utf-8');}
 if(b.dataset.normMore){normLimit[b.dataset.normMore]=1e9;render();return;}
 if(id==='export-all')download('inventory-all-projects.csv',E.csv([['Project ID','Dataset name','Laboratory','Project date','Contact','Assay as recorded','Assay class','Genome reference as recorded','Organism (proposed)','Reach','Public accession','Shiny link','Viewer link','Readiness score (0-8)','Needs next','Evidence answered','Source row'],...derivedRows()]),'text/csv;charset=utf-8');
});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.normField){const f=el.dataset.normField,k=el.dataset.normKey;state.norm[f]=state.norm[f]||{};const cur=state.norm[f][k]||{term:'',reviewer:''};cur[el.dataset.normProp]=el.value;state.norm[f][k]=cur;persist();return;}if(el.id.startsWith('e-')&&el.closest('#questions-form'))saveDraft();if(el.id==='project-search'){search=el.value;renderRows();}if(el.dataset.owner){review().owners[el.dataset.owner]=el.value;persist();}if(el.dataset.note){review().notes[el.dataset.note]=el.value;persist();}});
document.addEventListener('change',async e=>{const el=e.target;if(el.id.startsWith('q-')&&el.closest('#questions-form'))saveDraft();
 if(el.id==='project-select'){state.selected=el.value;render();}
 if(el.id==='goal-select'){state.goal=el.value;render();}
 if(el.id==='project-filter'){filter=el.value;renderRows();}
 if(el.id==='lab-filter'){labFilter=el.value;renderRows();}
 if(el.dataset.map&&pending)pending.map[el.dataset.map]=el.value;
 if((el.id==='v-sheet-file'||el.id==='v-listing-file')&&el.files[0]){const f=el.files[0];if(f.size>5_000_000){toast('File larger than 5 MB; paste a trimmed listing instead.');return;}const text=await f.text();$(el.id==='v-sheet-file'?'#v-sheet':'#v-listing').value=text;const rev=review();rev.validation={...(rev.validation||{sheet:'',listing:'',excluded:'',ran:''}),[el.id==='v-sheet-file'?'sheet':'listing']:text};persist();toast('Loaded '+f.name+'. Click Validate.');}
 if(el.id==='folder-input'&&el.files){$('#import-error').textContent='';await intakeFolder(el.files);el.value='';return;}
 if(el.id==='inventory-file'&&el.files[0]){const f=el.files[0];if(f.size>5_000_000){$('#import-error').textContent='Please use an inventory smaller than 5 MB.';return;}if(!/\.(csv|tsv)$/i.test(f.name)){$('#import-error').textContent='Please save the Excel sheet as CSV or TSV first.';return;}parseIntake(await f.text(),f.name);}
 if(el.id==='session-file'&&el.files[0]){try{if(el.files[0].size>10_000_000)throw Error('Session exceeds the 10 MB prototype limit.');const next=validateSession(JSON.parse(await el.files[0].text()));if(!confirm('Restore this session and replace the current working inventory and notes?'))return;state=next;search='';filter='all';labFilter='all';$('#intake-dialog').close();render();toast('Session restored.');}catch(error){$('#import-error').textContent='Could not restore session: '+error.message;}}
});
document.addEventListener('submit',e=>{if(e.target.id!=='questions-form')return;e.preventDefault();const next={...review().answers};for(const q of E.applicableQuestions(state.goal)){const value=$('#q-'+q.id).value,evidence=$('#e-'+q.id).value.trim();if(value!=='unknown'&&!evidence){$('#question-error').textContent='Add an evidence note for: '+q.label;$('#e-'+q.id).focus();return;}next[q.id]={value,evidence};}review().answers=next;delete review().drafts;persist();navigate('actions');toast('Evidence recorded. Preparation plan updated.');});
{const v=$('#app-version');if(v)v.textContent=VERSION;}
render();
})();
